{
  "name": "builder_all_pairs_gap_simple_001",
  "intuition": "Create deterministic pairwise preferences where, within each instance, any candidate with strictly lower objective is preferred over higher-objective candidates; an optional nonnegative gap_threshold ignores near-ties to reduce noisy comparisons.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']

    # Avoid builtins like float()/int(); use simple Python ops and defaults.
    gap_thr = extra.get('gap_threshold', 0.0)
    if gap_thr is None:
        gap_thr = 0.0
    try:
        gap_thr = 0.0 + gap_thr
    except Exception:
        gap_thr = 0.0
    if gap_thr < 0.0:
        gap_thr = 0.0

    # Pair i beats j if objective[i] + gap_thr < objective[j].
    # objective: (B, T)
    diff = objective[:, None, :] - objective[:, :, None]  # (B, T, T) = obj[j] - obj[i]
    mask = diff > gap_thr

    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)

    # Ensure 1D int64 indices.
    b_idx = b_idx.reshape(-1).to(dtype=objective.new_zeros((), dtype=objective.dtype).long().dtype)
    winner_idx = winner_idx.reshape(-1).to(dtype=b_idx.dtype)
    loser_idx = loser_idx.reshape(-1).to(dtype=b_idx.dtype)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={'builder': 'all_pairs_gap_simple', 'gap_threshold': gap_thr}
    )
"
}

{
  "name": "builder_all_pairs_gap_weight_001",
  "intuition": "Keep all objective-improving pairs but add a nonnegative weight proportional to the objective gap (with optional clipping), emphasizing clearer preferences and improving robustness to near-ties.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)

    # Nonnegative gap-based weights to emphasize stronger preferences.
    gap = (objective[b_idx, loser_idx] - objective[b_idx, winner_idx]).clamp(min=0)
    clip = extra.get('gap_clip', None) if isinstance(extra, dict) else None
    if clip is not None:
        gap = gap.clamp(max=clip)
    scale = extra.get('gap_scale', 1.0) if isinstance(extra, dict) else 1.0
    if scale is None or scale == 0:
        weight = gap
    else:
        weight = gap / float(scale)

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'gap_clip': clip, 'gap_scale': scale})
"
}

