    # Ensure required dtype/shape for indices.
    b_idx = b_idx.to(dtype=objective.new_empty((), dtype=objective.dtype).long().dtype)
    winner_idx = winner_idx.to(dtype=b_idx.dtype)
    loser_idx = loser_idx.to(dtype=b_idx.dtype)

    # Nonnegative gap-based weights to emphasize stronger preferences.
    gap = (objective[b_idx, loser_idx] - objective[b_idx, winner_idx]).clamp(min=0)

