        except Exception:
            clip = None
        try:
            scale = extra.get('gap_scale', 1.0)
        except Exception:
            scale = 1.0

    if clip is not None:
        gap = gap.clamp(max=clip)

    if scale is None or scale == 0:
        weight = gap
