        weight = gap / float(scale)

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'gap_clip': clip, 'gap_scale': scale})
