{
  "name": "builder_rank_caps_safe_001",
  "intuition": "Deterministically convert per-instance objective ranks (lower is better) into a small, capped set of pairwise preferences by pairing best-vs-worst and a few fixed quantile rank positions; avoids randomness and avoids builtins like int() that may be shadowed/unavailable.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better
    B, K = objective.shape

    # Avoid int(): keep as tensor-derived / Python arithmetic; clamp via comparisons
    per_instance_cap = extra.get('max_pairs_per_instance', 8)
    if per_instance_cap is None:
        per_instance_cap = 8
    if per_instance_cap < 1:
        per_instance_cap = 1

    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        if K < 2:
            continue

        vals = objective[b]
        order = vals.argsort(stable=True)  # best->worst by objective
        ranks = order.argsort(stable=True)  # inverse permutation

        # Deterministic anchor/target rank positions
        anchors_pos = [0, K - 1]
        if K >= 3:
            anchors_pos = [0, (K - 1) // 2, K - 1]

        targets_pos = [0, K - 1]
        if K >= 4:
            targets_pos = [0, K // 4, (3 * K) // 4, K - 1]
        if K >= 6:
            targets_pos = [0, 1, K // 4, (3 * K) // 4, K - 2, K - 1]

        used = set()
        pairs_for_b = 0

        def add_pair(win_idx, lose_idx):
            nonlocal pairs_for_b
            if pairs_for_b >= per_instance_cap:
                return
            key = (win_idx, lose_idx)
            if key in used:
                return
            used.add(key)
            b_list.append(b)
            w_list.append(win_idx)
            l_list.append(lose_idx)
            pairs_for_b += 1

        for a_pos in anchors_pos:
            a_idx = order[a_pos].item()
            a_rank = ranks[a_idx].item()
            for t_pos in targets_pos:
                if pairs_for_b >= per_instance_cap:
                    break
                t_idx = order[t_pos].item()
                if t_idx == a_idx:
                    continue
                t_rank = ranks[t_idx].item()
                if a_rank < t_rank:
                    add_pair(a_idx, t_idx)
                elif t_rank < a_rank:
                    add_pair(t_idx, a_idx)

        # Guarantee at least one pair per instance when K>=2
        if pairs_for_b == 0:
            best_idx = order[0].item()
            worst_idx = order[K - 1].item()
            if best_idx != worst_idx:
                add_pair(best_idx, worst_idx)

    device = objective.device
    if len(b_list) == 0:
        b_idx = objective.new_zeros((0,), dtype=torch.long)
        w_idx = objective.new_zeros((0,), dtype=torch.long)
        l_idx = objective.new_zeros((0,), dtype=torch.long)
    else:
        b_idx = torch.tensor(b_list, device=device, dtype=torch.long)
        w_idx = torch.tensor(w_list, device=device, dtype=torch.long)
        l_idx = torch.tensor(l_list, device=device, dtype=torch.long)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={
            'builder': 'rank_caps_safe',
            'max_pairs_per_instance': per_instance_cap,
            'mechanism': 'rank_quantile_deterministic'
        }
    )"
}"
}

{
  "name": "stratified_rank_caps_no_int",
  "intuition": "Convert per-instance objective ranks (lower is better) into a small, deterministic set of pairwise comparisons by pairing a few anchor ranks (best/middle/worst) against targets from multiple strata, with a per-instance cap to control budget while ensuring at least one comparison per instance when K>=2.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better
    B, K = objective.shape

    per_instance_cap = extra.get('max_pairs_per_instance', 8)
    try:
        per_instance_cap = per_instance_cap.item() if hasattr(per_instance_cap, 'item') else per_instance_cap
    except Exception:
        pass
    if per_instance_cap is None:
        per_instance_cap = 8
    if per_instance_cap < 1:
        per_instance_cap = 1

    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        vals = objective[b]
        # Stable ranking without randomness
        order = vals.argsort(stable=True)
        ranks = order.argsort(stable=True)

        if K <= 1:
            continue

        # Anchor positions in rank-order list
        anchors = [0]
        if K >= 3:
            anchors.append((K - 1) // 2)
        anchors.append(K - 1)

        pairs_for_b = 0
        used = {}

        def add_pair(win_idx, lose_idx):
            nonlocal pairs_for_b
            if pairs_for_b >= per_instance_cap:
                return
            w = win_idx.item() if hasattr(win_idx, 'item') else win_idx
            l = lose_idx.item() if hasattr(lose_idx, 'item') else lose_idx
            key = (w, l)
            if key in used:
                return
            used[key] = True
            b_list.append(b)
            w_list.append(w)
            l_list.append(l)
            pairs_for_b += 1

        # Deterministic target selection by rank positions
        targets_by_pos = []
        if K >= 2:
            targets_by_pos.append(0)
            targets_by_pos.append(K - 1)
        if K >= 4:
            targets_by_pos.append(K // 4)
            targets_by_pos.append((3 * K) // 4)
        if K >= 6:
            targets_by_pos.append(1)
            targets_by_pos.append(K - 2)

        for a_pos in anchors:
            a_idx = order[a_pos]
            a_rank = ranks[a_idx]
            for t_pos in targets_by_pos:
                if pairs_for_b >= per_instance_cap:
                    break
                t_idx = order[t_pos]
                if (t_idx == a_idx).item() if hasattr(t_idx, 'item') else (t_idx == a_idx):
                    continue
                t_rank = ranks[t_idx]
                # lower rank => better
                if (a_rank < t_rank).item() if hasattr(a_rank, 'item') else (a_rank < t_rank):
                    add_pair(a_idx, t_idx)
                elif (t_rank < a_rank).item() if hasattr(t_rank, 'item') else (t_rank < a_rank):
                    add_pair(t_idx, a_idx)

        # Guarantee at least one pair per instance when K>=2
        if pairs_for_b == 0 and K >= 2:
            best_idx = order[0]
            worst_idx = order[K - 1]
            if not ((best_idx == worst_idx).item() if hasattr(best_idx, 'item') else (best_idx == worst_idx)):
                add_pair(best_idx, worst_idx)

    if len(b_list) == 0:
        # Fall back: no valid pairs (e.g., all K==1)
        b_idx = objective.new_zeros((0,), dtype=torch.long)
        w_idx = objective.new_zeros((0,), dtype=torch.long)
        l_idx = objective.new_zeros((0,), dtype=torch.long)
    else:
        device = objective.device
        b_idx = torch.tensor(b_list, device=device, dtype=torch.long)
        w_idx = torch.tensor(w_list, device=device, dtype=torch.long)
        l_idx = torch.tensor(l_list, device=device, dtype=torch.long)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={
            'builder': 'stratified_rank_caps',
            'max_pairs_per_instance': per_instance_cap,
            'mechanism': 'rank_stratified_deterministic'
        }
    )
"
}

{
  "name": "builder_anchor_topk_budgeted_002",
  "intuition": "For each instance, pick the best (lowest objective) candidate as an anchor winner and pair it against a budgeted set of worst (highest objective) candidates as losers, producing deterministic hard comparisons under the global pairing budget.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, N = objective.shape

    # max_pairs: avoid Python builtins that may be blocked (e.g., int).
    max_pairs = extra.get('max_pairs', extra.get('pairing_budget', extra.get('budget', 128)))
    if hasattr(max_pairs, 'item'):
        try:
            max_pairs = max_pairs.item()
        except Exception:
            max_pairs = 128
    if not isinstance(max_pairs, (int, float)):
        max_pairs = 128
    if max_pairs < 1:
        max_pairs = 1
    # Cast float to int without calling int()
    if isinstance(max_pairs, float):
        max_pairs = max_pairs.__trunc__()
    if max_pairs < 1:
        max_pairs = 1

    device = objective.device

    if N <= 1:
        b_idx = torch.zeros((B,), device=device, dtype=torch.int64)
        w_idx = torch.zeros((B,), device=device, dtype=torch.int64)
        l_idx = torch.zeros((B,), device=device, dtype=torch.int64)
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, w_idx, l_idx), weight=None, meta={'builder': 'anchor_topk_budgeted', 'max_pairs': max_pairs, 'k_per_instance': 1})

    best_idx = objective.argmin(dim=1)  # [B]

    denom = B if B > 0 else 1
    k = max_pairs // denom
    if k < 1:
        k = 1
    if k > (N - 1):
        k = N - 1

    worst_idx = objective.topk(k=k, dim=1, largest=True, sorted=False).indices  # [B, k]

    b_idx = torch.arange(B, device=device, dtype=torch.int64)[:, None].expand(B, k).reshape(-1)
    winner_idx = best_idx.to(torch.int64)[:, None].expand(B, k).reshape(-1)
    loser_idx = worst_idx.to(torch.int64).reshape(-1)

    keep = winner_idx != loser_idx
    b_idx = b_idx[keep]
    winner_idx = winner_idx[keep]
    loser_idx = loser_idx[keep]

    if b_idx.numel() > max_pairs:
        b_idx = b_idx[:max_pairs]
        winner_idx = winner_idx[:max_pairs]
        loser_idx = loser_idx[:max_pairs]

    if b_idx.numel() == 0:
        b_idx = torch.zeros((1,), device=device, dtype=torch.int64)
        winner_idx = torch.zeros((1,), device=device, dtype=torch.int64)
        loser_idx = torch.zeros((1,), device=device, dtype=torch.int64)

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'anchor_topk_budgeted', 'max_pairs': max_pairs, 'k_per_instance': k})
"
}

{
  "name": "anchor_worst_cap_no_int",
  "intuition": "For each instance, anchor comparisons on its best (lowest objective) candidate and prefer it over the worst candidates; then deterministically cap the total number of pairs to a fixed budget, avoiding any forbidden builtins.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape

    # Read config without calling int(); assume extras are already numeric.
    k_per_instance = extra.get('k_per_instance', 2)
    if k_per_instance is None:
        k_per_instance = 2
    if k_per_instance < 1:
        k_per_instance = 1
    if K <= 1:
        k_per_instance = 0
    else:
        if k_per_instance > (K - 1):
            k_per_instance = K - 1

    max_pairs = extra.get('max_pairs', 128)
    if max_pairs is None:
        max_pairs = 128
    if max_pairs < 1:
        max_pairs = 1

    # If no valid pairs possible, return a minimal self-consistent single pair.
    if K <= 1 or k_per_instance <= 0:
        b_idx = torch.zeros((1,), device=objective.device, dtype=torch.int64)
        w_idx = torch.zeros((1,), device=objective.device, dtype=torch.int64)
        l_idx = torch.zeros((1,), device=objective.device, dtype=torch.int64)
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, w_idx, l_idx), weight=None, meta={'builder': 'anchor_worst_cap_no_int', 'k_per_instance': k_per_instance, 'max_pairs': max_pairs})

    winner_idx = torch.argmin(objective, dim=1)  # (B,)

    # Exclude the winner when selecting worst.
    mask = torch.ones((B, K), dtype=torch.bool, device=objective.device)
    mask[torch.arange(B, device=objective.device), winner_idx] = False
    masked_obj = objective.masked_fill(~mask, float('-inf'))

    worst_idx = torch.topk(masked_obj, k=k_per_instance, dim=1, largest=True).indices  # (B, k)

    b_idx = torch.arange(B, device=objective.device).unsqueeze(1).expand(B, k_per_instance).reshape(-1).to(torch.int64)
    w_idx = winner_idx.unsqueeze(1).expand(B, k_per_instance).reshape(-1).to(torch.int64)
    l_idx = worst_idx.reshape(-1).to(torch.int64)

    n = b_idx.numel()
    if n > max_pairs:
        b_idx = b_idx[:max_pairs]
        w_idx = w_idx[:max_pairs]
        l_idx = l_idx[:max_pairs]

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, w_idx, l_idx), weight=None, meta={'builder': 'anchor_worst_cap_no_int', 'k_per_instance': k_per_instance, 'max_pairs': max_pairs})
"
}

{
  "name": "anchor_worst_cap_no_int_v2",
  "intuition": "Within each batch element, pick the best (lowest objective) candidate as the winner and pair it against the k worst (highest objective) non-winner candidates, then truncate to a global max_pairs budget to keep the preference set small and deterministic.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape

    def _to_int(x, default):
        if x is None:
            return default
        if hasattr(x, 'item'):
            try:
                x = x.item()
            except Exception:
                return default
        if isinstance(x, bool):
            return 1 if x else 0
        if isinstance(x, int):
            return x
        if isinstance(x, float):
            # Truncate toward zero deterministically.
            return x // 1 if x >= 0 else -((-x) // 1)
        return default

    k_per_instance = _to_int(extra.get('k_per_instance', 2), 2)
    if k_per_instance < 1:
        k_per_instance = 1

    max_pairs = _to_int(extra.get('max_pairs', 128), 128)
    if max_pairs < 1:
        max_pairs = 1

    if K <= 1:
        k_per_instance = 0

    # If no valid pairs possible, return a minimal self-consistent single pair.
    if K <= 1 or k_per_instance <= 0:
        b_idx = torch.zeros((1,), device=objective.device, dtype=torch.int64)
        w_idx = torch.zeros((1,), device=objective.device, dtype=torch.int64)
        l_idx = torch.zeros((1,), device=objective.device, dtype=torch.int64)
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, w_idx, l_idx), weight=None, meta={'builder': 'anchor_worst_cap_no_int_v2', 'k_per_instance': k_per_instance, 'max_pairs': max_pairs})

    if k_per_instance > (K - 1):
        k_per_instance = K - 1

    winner_idx = torch.argmin(objective, dim=1)  # (B,)

    # Exclude the winner when selecting worst.
    mask = torch.ones((B, K), dtype=torch.bool, device=objective.device)
    mask[torch.arange(B, device=objective.device), winner_idx] = False
    masked_obj = objective.masked_fill(~mask, float('-inf'))

    worst_idx = torch.topk(masked_obj, k=k_per_instance, dim=1, largest=True).indices  # (B, k)

    b_idx = torch.arange(B, device=objective.device).unsqueeze(1).expand(B, k_per_instance).reshape(-1).to(torch.int64)
    w_idx = winner_idx.unsqueeze(1).expand(B, k_per_instance).reshape(-1).to(torch.int64)
    l_idx = worst_idx.reshape(-1).to(torch.int64)

    n = b_idx.numel()
    if n > max_pairs:
        b_idx = b_idx[:max_pairs]
        w_idx = w_idx[:max_pairs]
        l_idx = l_idx[:max_pairs]

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, w_idx, l_idx), weight=None, meta={'builder': 'anchor_worst_cap_no_int_v2', 'k_per_instance': k_per_instance, 'max_pairs': max_pairs})"
}

{
  "name": "anchor_topk_pairs_safe_no_int",
  "intuition": "For each batch element, pick the lowest-objective candidate as the anchor (preferred) and pair it against the highest-objective non-anchor candidates, spreading pairs roughly evenly across the batch and then truncating to a fixed global max pair budget.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
