  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape

    # One anchor (best / lowest objective) per instance.
    anchor = objective.argmin(dim=1)

    # Determine budgets without calling int()/max() (may be unavailable).
    max_pairs = extra.get('max_pairs', 128)
    if max_pairs is None:
        max_pairs = 128
    if max_pairs < 1:
        max_pairs = 1

    per_inst = extra.get('per_instance', None)
    if per_inst is None:
        # Ceil(max_pairs / B) without Python max() and with B>=1.
        if B <= 1:
            per_inst = max_pairs
        else:
            per_inst = (max_pairs + B - 1) // B

    # Clamp per_inst to [1, K-1].
    if per_inst < 1:
        per_inst = 1
    if K <= 1:
        per_inst = 0
    else:
        if per_inst > (K - 1):
            per_inst = K - 1

    # If we can't form pairs, return an empty-but-valid batch.
    if per_inst == 0:
        empty = torch.zeros((0,), device=objective.device, dtype=torch.int64)
        return PrefBatch(mode='pairwise', pair_idx=(empty, empty, empty), weight=None, meta={'builder': 'anchor_topk_safe_no_int', 'max_pairs': max_pairs, 'per_instance': per_inst})

