    ar = torch.arange(K, device=objective.device)[None, :].expand(B, K)
    is_anchor = ar.eq(anchor[:, None])
    masked_obj = objective.masked_fill(is_anchor, -float('inf'))
    opp = masked_obj.topk(k=per_inst, dim=1, largest=True).indices

