    loser_idx = opp.to(dtype=torch.int64).reshape(-1)

    # Enforce global cap deterministically.
    if b_idx.numel() > max_pairs:
        b_idx = b_idx[:max_pairs]
        winner_idx = winner_idx[:max_pairs]
        loser_idx = loser_idx[:max_pairs]

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'anchor_topk_safe_no_int', 'max_pairs': max_pairs, 'per_instance': per_inst})
